/**
 * Sync engine offline-first — socle transverse de Resto Plus / PalaceOS.
 *
 * Principe : toute action utilisateur (checklist, déplacement de table,
 * message) est d'abord écrite en local (queue), puis rejouée vers le
 * backend dès que le réseau est disponible. En cas de conflit, résolution
 * par timestamp + priorité métier (ex : une validation HACCP est prioritaire
 * sur un simple déplacement de table).
 *
 * v2 : persistance via StorageAdapter (AsyncStorage / MMKV selon env),
 * backoff exponentiel sur les erreurs réseau.
 */

export type SyncActionType =
  | "checklist_entry"
  | "table_move"
  | "table_status_change"
  | "message_send";

export interface QueuedAction<T = unknown> {
  id: string;
  type: SyncActionType;
  payload: T;
  createdAt: string;
  attempts: number;
  status: "pending" | "syncing" | "synced" | "failed";
}

/** Abstraction de stockage — injecter AsyncStorage ou MMKV */
export interface StorageAdapter {
  getItem(key: string): Promise<string | null>;
  setItem(key: string, value: string): Promise<void>;
}

export interface SyncEngineOptions {
  /** Appelé pour envoyer une action au backend. Doit lever une erreur si ça échoue. */
  send: (action: QueuedAction) => Promise<void>;
  /** Adaptateur de stockage pour la persistance de la queue. */
  storage?: StorageAdapter;
  /** Intervalle de base pour le retry en ms (défaut : 5000). */
  baseRetryIntervalMs?: number;
  /** Nombre max de tentatives avant abandon définitif. */
  maxAttempts?: number;
  /** Appelé quand le pendingCount change (pour mise à jour du store UI). */
  onPendingCountChange?: (count: number) => void;
}

const STORAGE_KEY = "sync_engine_queue_v1";
const DEFAULT_BASE_INTERVAL = 5_000;
const DEFAULT_MAX_ATTEMPTS = 5;

export class SyncEngine {
  private queue: QueuedAction[] = [];
  private isOnline = true;
  private options: SyncEngineOptions;
  private retryTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(options: SyncEngineOptions) {
    this.options = options;
  }

  /** Charger la queue persistée — à appeler au démarrage de l'app. */
  async hydrate(): Promise<void> {
    if (!this.options.storage) return;
    try {
      const raw = await this.options.storage.getItem(STORAGE_KEY);
      if (raw) {
        const saved = JSON.parse(raw) as QueuedAction[];
        // Remettre les actions "syncing" en "pending" (crash en cours de flush)
        this.queue = saved.map((a) =>
          a.status === "syncing" ? { ...a, status: "pending" } : a
        );
        this._notifyCount();
        if (this.isOnline) void this.flush();
      }
    } catch {
      // Stockage corrompu : on repart d'une queue vide
      this.queue = [];
    }
  }

  enqueue<T>(type: SyncActionType, payload: T): QueuedAction<T> {
    const action: QueuedAction<T> = {
      id: `${type}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      type,
      payload,
      createdAt: new Date().toISOString(),
      attempts: 0,
      status: "pending",
    };
    this.queue.push(action as QueuedAction);
    this._persist();
    this._notifyCount();
    if (this.isOnline) void this.flush();
    return action;
  }

  setOnline(online: boolean) {
    this.isOnline = online;
    if (online) {
      this._clearRetryTimer();
      void this.flush();
    }
  }

  getPendingCount(): number {
    return this.queue.filter((a) => a.status !== "synced").length;
  }

  private async flush() {
    const maxAttempts = this.options.maxAttempts ?? DEFAULT_MAX_ATTEMPTS;

    for (const action of this.queue) {
      if (action.status === "synced") continue;
      if (action.attempts >= maxAttempts) {
        action.status = "failed";
        continue;
      }
      action.status = "syncing";
      try {
        await this.options.send(action);
        action.status = "synced";
      } catch {
        action.attempts += 1;
        action.status = "failed";
      }
    }

    // Nettoyer les actions définitivement syncées
    this.queue = this.queue.filter((a) => a.status !== "synced");

    this._persist();
    this._notifyCount();

    // S'il reste des actions échouées/en attente et qu'on est en ligne, programmer un retry
    const hasPending = this.queue.some(
      (a) => a.status === "failed" && a.attempts < maxAttempts
    );
    if (hasPending && this.isOnline) {
      this._scheduleRetry();
    }
  }

  private _scheduleRetry() {
    this._clearRetryTimer();
    // Backoff exponentiel basé sur le min attempts de la queue
    const minAttempts = Math.min(...this.queue.map((a) => a.attempts));
    const base = this.options.baseRetryIntervalMs ?? DEFAULT_BASE_INTERVAL;
    const delay = base * Math.pow(2, minAttempts);
    this.retryTimer = setTimeout(() => {
      if (this.isOnline) void this.flush();
    }, delay);
  }

  private _clearRetryTimer() {
    if (this.retryTimer !== null) {
      clearTimeout(this.retryTimer);
      this.retryTimer = null;
    }
  }

  private async _persist() {
    if (!this.options.storage) return;
    try {
      await this.options.storage.setItem(
        STORAGE_KEY,
        JSON.stringify(this.queue)
      );
    } catch {
      // Silencieux : le pire cas est une perte de queue au redémarrage
    }
  }

  private _notifyCount() {
    this.options.onPendingCountChange?.(this.getPendingCount());
  }
}
